    if (drag.kind === 'O') {
      O.x = Math.max(20, Math.min(W * 0.45, O.x + dx));
      O.y = Math.max(40, Math.min(H - 30, O.y + dy));
    } else {
      var t = trans[drag.key];
      t.p.x += dx; t.p.y += dy;
    }
    render();
  });
  window.addEventListener('mouseup', function () { drag = null; });

  // ---------- controls ----------
  window.update_rLineAngle = function (v) { rAngleOffset = v; render(); };
  window.toggle_showLengths = function (on) { state.lengths = on; render(); };
  window.set_activeSet = function (v) { state.active = v; render(); };
  window.trigger_reset = function () {
    O.x = defaults.O.x; O.y = defaults.O.y;
    ['P', 'Q', 'R'].forEach(function (k) {
      trans[k].p.x = defaults.trans[k].p.x;
      trans[k].p.y = defaults.trans[k].p.y;
      trans[k].ang = defaults.trans[k].ang;
    });
    render();
  };

  // ---------- demo steps ----------
  var steps = [
    { title: 'A pencil of four rays', n: 'Four lines radiate from the projection center O. Think of O as a camera pinhole and the rays as sight-lines to four collinear world points.', s: { activeSet: 'all', showLengths: false, rLineAngle: 0 } },
    { title: 'The first cut: P₁…P₄', n: "A transversal slices the pencil at P₁…P₄. This quadruple is one 'image' of the scene; its cross-ratio (P₁P₃·P₂P₄)/(P₂P₃·P₁P₄) is shown in the readout.", s: { activeSet: 'P', showLengths: true, rLineAngle: 0 } },
    { title: 'A second cut gives different distances', n: 'The Q transversal cuts the same four rays at very different spacings — every individual length has changed — but the cross-ratio readout is identical.', s: { activeSet: 'Q', showLengths: true, rLineAngle: 0 } },
    { title: 'Drag anything you like', n: 'Drag the crimson transversals or drag O itself. Lengths, angles and ordering on screen all shift, yet the three cross-ratio numbers stay welded together.', s: { activeSet: 'all', showLengths: true, rLineAngle: 0 } },
    { title: 'Sending R₁ to infinity', n: 'The R transversal is parallel to ray 1, so R₁ runs off the page. The cross-ratio does not break — it becomes the plain ratio R₂R₄/R₂R₃. Rotate the slider away from 0 to bring R₁ back from infinity.', s: { activeSet: 'R', showLengths: true, rLineAngle: 0 } },
    { title: 'One invariant, three views', n: 'All three quadruples — including the degenerate one containing a point at infinity — share a single number. That number is a property of the 3D scene recoverable from one image.', s: { activeSet: 'all', showLengths: false, rLineAngle: 0 } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    document.getElementById('demoNarration').innerHTML = '<b>' + st.title + '</b><br>' + st.n;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    var a = document.getElementById('activeSetInput'); a.value = st.s.activeSet; state.active = st.s.activeSet;
    var c = document.getElementById('showLengthsInput'); c.checked = st.s.showLengths; state.lengths = st.s.showLengths;
    var r = document.getElementById('rLineAngleInput'); r.value = st.s.rLineAngle;
    document.getElementById('rLineAngleVal').value = st.s.rLineAngle;
    rAngleOffset = st.s.rLineAngle;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

