    if (inf < 0) {
      var num = (t[2] - t[0]) * (t[3] - t[1]);
      var den = (t[2] - t[1]) * (t[3] - t[0]);
      return den === 0 ? NaN : num / den;
    }
    if (inf === 0) return (t[3] - t[1]) / (t[2] - t[1]);
    if (inf === 1) return (t[2] - t[0]) / (t[3] - t[0]);
    if (inf === 2) return (t[3] - t[1]) / (t[3] - t[0]);
    return (t[2] - t[0]) / (t[2] - t[1]);
  }

  // ---------- layers ----------
  var gRays = draw.group();
  var gLines = draw.group();
  var gHandles = draw.group();
  var gLens = draw.group();
  var gDots = draw.group();
  var gLabels = draw.group();

  function halo(t, w) {
    return t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (w || 4.5), 'stroke-linejoin': 'round' });
  }
  function subText(group, main, subs, size, color) {
    return group.text(function (add) {
      add.tspan(main).font({ size: size, weight: 'bold', family: 'Georgia, serif' });
      add.tspan(subs).font({ size: size * 0.66, weight: 'bold', family: 'Georgia, serif' }).dy(size * 0.27);
    }).fill(color);
  }

  var state = { active: 'all', lengths: false };

  // forward exit point of a ray inside the frame
  function rayEnd(d) {
    var ts = [];
    if (d.x > 1e-9) ts.push((W - 3 - O.x) / d.x);
    if (d.x < -1e-9) ts.push((3 - O.x) / d.x);
    if (d.y > 1e-9) ts.push((H - 3 - O.y) / d.y);
    if (d.y < -1e-9) ts.push((3 - O.y) / d.y);
    var t = Math.min.apply(null, ts.filter(function (v) { return v > 0; }));
    if (!isFinite(t)) t = 2000;
    return { x: O.x + t * d.x, y: O.y + t * d.y };
  }

  // ---------- label placement (collision aware) ----------
  var PREF = {
    P: [[24, 26], [26, 8], [30, 40], [-30, 26], [26, -16], [-32, -8]],
    Q: [[32, 16], [26, -20], [32, -4], [30, 34], [-34, 16], [-32, -16]],
    R: [[0, -28], [26, -26], [-26, -26], [26, 22], [-28, 20], [0, 32]],
    O: [[-30, -20], [-30, 22], [26, -26]]
  };
  function distPointSeg(c, a, b) {
    var vx = b.x - a.x, vy = b.y - a.y, L2 = vx * vx + vy * vy;
    var t = L2 ? ((c.x - a.x) * vx + (c.y - a.y) * vy) / L2 : 0;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(c.x - (a.x + t * vx), c.y - (a.y + t * vy));
  }
  function placeLabel(key, p, segs, dots, rects) {
    var prefs = PREF[key], best = null, bestS = -1e9;
    for (var i = 0; i < prefs.length; i++) {
      var c = { x: p.x + prefs[i][0], y: p.y + prefs[i][1] };
      var s = 1e9, j;
      for (j = 0; j < segs.length; j++) s = Math.min(s, distPointSeg(c, segs[j].a, segs[j].b));
      for (j = 0; j < dots.length; j++) {
        var dd = Math.hypot(c.x - dots[j].x, c.y - dots[j].y);
        if (dd > 0.5) s = Math.min(s, dd - 11);
      }
      s = Math.min(s, 30);
      for (j = 0; j < rects.length; j++) {
        var r = rects[j];
        if (Math.abs(c.x - r.x) < 36 && Math.abs(c.y - r.y) < 28) s -= 70;
      }
      if (c.x < 22 || c.x > W - 22 || c.y < 20 || c.y > H - 18) s -= 90;
      s += (prefs.length - i) * 2.2;
      if (s > bestS) { bestS = s; best = c; }
    }
    rects.push(best);
    return best;
  }

  // ---------- render ----------
  var cache = {};
  function render() {
    gRays.clear(); gLines.clear(); gHandles.clear(); gDots.clear(); gLabels.clear(); gLens.clear();

    var segs = [], dots = [], rects = [];

    // rays
    var ends = [];
    for (var i = 0; i < 4; i++) {
      var e = rayEnd(rays[i].d);
      ends.push(e);
      segs.push({ a: { x: O.x, y: O.y }, b: e });
      gRays.line(O.x, O.y, e.x, e.y).stroke({ color: BLACK, width: 2.2, linecap: 'round' })
        .css('cursor', 'pointer')
        .on('mousemove', (function (n) { return function (ev) { showTooltip('Ray ' + n + ' from O — one sight-line of the pencil', ev); }; })(i + 1))
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The pencil of rays', 'All four rays pass through the projection center O. Any transversal cutting them gives four collinear points — one "image" of the same scene. The cross-ratio of those four points is the same for every transversal.');
        });
    }

    // transversal data
    var keys = ['P', 'Q', 'R'], data = {};
    keys.forEach(function (k) {
      var d = dirOf(k), lp = trans[k].p, pts = [], tpar = [];
      for (var i = 0; i < 4; i++) {
        var ip = intersect(rays[i].d, lp, d);
        if (ip && Math.abs(rays[i].d.x * d.y - rays[i].d.y * d.x) > 2.2e-3) { pts.push(ip); tpar.push(paramOn(ip, lp, d)); }
        else { pts.push(null); tpar.push(null); }
      }
      data[k] = { pts: pts, t: tpar, dir: d, lp: lp, cr: crossRatio(tpar) };
    });
    cache = data;

    // transversal lines
    keys.forEach(function (k) {
      var active = (state.active === 'all' || state.active === k);
      var ts = data[k].t.filter(function (v) { return v !== null && Math.abs(v) < 4000; });
      if (!ts.length) return;
      var ex = trans[k].ext;
      var lo = Math.min.apply(null, ts) - ex, hi = Math.max.apply(null, ts) + ex;
      var a = { x: trans[k].p.x + lo * data[k].dir.x, y: trans[k].p.y + lo * data[k].dir.y };
      var b = { x: trans[k].p.x + hi * data[k].dir.x, y: trans[k].p.y + hi * data[k].dir.y };
      segs.push({ a: a, b: b });
      gLines.line(a.x, a.y, b.x, b.y)
        .stroke({ color: active ? CRIM : DIM, width: active ? 3.4 : 2.4, linecap: 'round' });
      gHandles.line(a.x, a.y, b.x, b.y).stroke({ color: '#000', width: 20, opacity: 0 })
        .css('cursor', 'move')
        .on('mousemove', function (ev) { showTooltip('Drag this transversal — every distance changes, the cross-ratio does not', ev); })
        .on('mouseleave', hideTooltip)
        .on('mousedown', (function (kk) { return function (ev) { startDrag(ev, 'line', kk); }; })(k));
    });

    // dots
    keys.forEach(function (k) {
      var active = (state.active === 'all' || state.active === k);
      for (var i = 0; i < 4; i++) {
        var p = data[k].pts[i];
        if (!p) continue;
        if (p.x < -20 || p.x > W + 20 || p.y < -20 || p.y > H + 20) continue;
        dots.push(p);
        gDots.circle(active ? 18 : 12).center(p.x, p.y).fill(active ? BLACK : DIM)
          .css('cursor', 'pointer')
          .on('mousemove', (function (kk, ii) {
            return function (ev) { showTooltip(kk + (ii + 1) + ' — where ray ' + (ii + 1) + ' meets the ' + kk + ' transversal', ev); };
          })(k, i))
          .on('mouseleave', hideTooltip)
          .on('click', (function (kk) {
            return function () {
              showPopup('One quadruple, one number', 'These four points are the image of the pencil on the ' + kk + ' line. Their spacings differ completely from the other transversals, yet (AC·BD)/(BC·AD) comes out the same: ' + fmt(data[kk].cr) + '.');
            };
          })(k));
      }
    });
    dots.push({ x: O.x, y: O.y });
    gDots.circle(21).center(O.x, O.y).fill(BLACK).css('cursor', 'grab')
      .on('mousemove', function (ev) { showTooltip('Drag O — the center of projection', ev); })
      .on('mouseleave', hideTooltip)
      .on('mousedown', function (ev) { startDrag(ev, 'O'); })
      .on('click', function () {
        showPopup('The center of projection', 'O plays the role of a camera pinhole. Re-aiming the pencil by moving O changes every intersection point on every transversal, yet the three cross-ratios stay equal to each other.');
      });

    // labels (O first, then P, Q, R)
    var oc = placeLabel('O', { x: O.x, y: O.y }, segs, dots, rects);
    halo(gLabels.text('O').font({ size: 26, weight: 'bold', family: 'Georgia, serif' }).fill(BLACK)).center(oc.x, oc.y);

    keys.forEach(function (k) {
      var active = (state.active === 'all' || state.active === k);
      for (var i = 0; i < 4; i++) {
        var p = data[k].pts[i];
        if (!p) continue;
        if (p.x < -20 || p.x > W + 20 || p.y < -20 || p.y > H + 20) continue;
        var c = placeLabel(k, p, segs, dots, rects);
        var t = subText(gLabels, k, String(i + 1), 25, active ? BLACK : DIMTX);
        halo(t).center(c.x, c.y);
      }
    });

    // R1 → ∞ annotation
    var rInf = (data.R.pts[0] === null || Math.abs(data.R.t[0]) > 2500);
    if (rInf) {
      var r2 = data.R.pts[1];
      var ax = r2 ? Math.min(W - 108, r2.x + 62) : W - 150;
      var ay = O.y + rays[1].d.y * ((ax - O.x) / rays[1].d.x) - 17;
      ay = Math.max(24, Math.min(H - 24, ay));
      var g = gLabels.group();
      halo(subText(g, 'R', '1', 25, BLACK)).center(ax, ay);
      g.line(ax + 22, ay - 1, ax + 56, ay - 1).stroke({ color: BLACK, width: 2.6 });
      g.polygon([[ax + 54, ay - 8], [ax + 70, ay - 1], [ax + 54, ay + 6]]).fill(BLACK);
      halo(g.text('∞').font({ size: 30, family: 'Georgia, serif' }).fill(BLACK)).center(ax + 88, ay - 2);
      g.css('cursor', 'pointer')
        .on('mousemove', function (ev) { showTooltip('R₁ has escaped to infinity: the R line is parallel to ray 1', ev); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('A point at infinity', 'Because the R transversal is parallel to ray 1, their intersection R₁ lies at infinity. The cross-ratio does not blow up — the two factors containing R₁ cancel and it degenerates to the plain ratio R₂R₄ / R₂R₃.');
        });
    }

    if (state.lengths) drawLengths(data);
    updatePanel(data, rInf);
  }

  function fmt(v) {
    if (!isFinite(v)) return '∞';
    return (Math.round(v * 1000) / 1000).toFixed(3);
  }

  // ---------- segment length overlay ----------
  var SUB = ['₁', '₂', '₃', '₄'];
  function drawLengths(data) {
    ['P', 'Q', 'R'].forEach(function (k) {
      if (state.active !== 'all' && state.active !== k) return;
      var pts = data[k].pts, t = data[k].t;
      var pairs = [[0, 2, '#1466b0', 13], [1, 3, '#1466b0', 31], [1, 2, '#c07800', -13], [0, 3, '#c07800', -31]];
      pairs.forEach(function (pr) {
        var a = pts[pr[0]], b = pts[pr[1]];
        if (!a || !b) return;
        var dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy);
        if (L < 10) return;
        var nx = -dy / L, ny = dx / L, o = pr[3] * 0.55;
        var A = { x: a.x + nx * o, y: a.y + ny * o }, B = { x: b.x + nx * o, y: b.y + ny * o };
        gLens.line(A.x, A.y, B.x, B.y).stroke({ color: pr[2], width: 1.8, opacity: 0.9 })
          .attr('stroke-dasharray', pr[3] > 0 ? null : '5,4');
        var mx = (A.x + B.x) / 2 + nx * (pr[3] > 0 ? 11 : -11);
        var my = (A.y + B.y) / 2 + ny * (pr[3] > 0 ? 11 : -11);
        var tx = gLens.text(k + SUB[pr[0]] + k + SUB[pr[1]] + ' = ' + Math.round(Math.abs(t[pr[1]] - t[pr[0]])))
          .font({ size: 13, family: 'sans-serif' }).fill(pr[2]);
        halo(tx, 4).center(mx, my);
      });
    });
  }

  // ---------- readout panel (in the side UI column) ----------
  function updatePanel(data, rInf) {
    var vals = [data.P.cr, data.Q.cr, data.R.cr], agree = true;
    for (var i = 1; i < 3; i++) {
      if (!(isFinite(vals[0]) && isFinite(vals[i]) &&
        Math.abs(vals[i] - vals[0]) < 1e-6 * Math.max(1, Math.abs(vals[0])))) agree = false;
    }
    var accent = agree ? '#0a8f4d' : '#444';
    var names = ['P', 'Q', 'R'], html = '';
    for (var j = 0; j < 3; j++) {
      var faded = (state.active !== 'all' && state.active !== names[j]);
      var n = names[j];
      html += '<span style="display:flex;justify-content:space-between;gap:8px;' +
        (faded ? 'opacity:.45;' : '') + '">' +
        '<span>CR(' + n + '₁,' + n + '₂;' + n + '₃,' + n + '₄)</span>' +
        '<b style="color:' + accent + '">= ' + fmt(vals[j]) + '</b></span>';
    }
    document.getElementById('crRows').innerHTML = html;
    document.getElementById('crNote').textContent = rInf
      ? 'R₁ is at infinity → CR = R₂R₄ / R₂R₃'
      : (agree ? 'All three transversals agree.' : '');
  }

  // ---------- dragging ----------
  var drag = null;
  function svgPoint(ev) {
    var r = draw.node.getBoundingClientRect();
    return { x: (ev.clientX - r.left) / r.width * W, y: (ev.clientY - r.top) / r.height * H };
  }
  function startDrag(ev, kind, key) { ev.preventDefault(); drag = { kind: kind, key: key, last: svgPoint(ev) }; }
  window.addEventListener('mousemove', function (ev) {
    if (!drag) return;
    var p = svgPoint(ev), dx = p.x - drag.last.x, dy = p.y - drag.last.y;
    drag.last = p;
    if (drag.kind === 'O') {
      O.x = Math.max(22, Math.min(W * 0.35, O.x + dx));
      O.y = Math.max(45, Math.min(H - 35, O.y + dy));
    } else {
      var t = trans[drag.key];
      t.p.x = Math.max(60, Math.min(W - 60, t.p.x + dx));
      t.p.y = Math.max(10, Math.min(H - 10, t.p.y + dy));
    }
    render();
  });
  window.addEventListener('mouseup', function () { drag = null; });

  // ---------- controls ----------
  window.update_rLineAngle = function (v) { rAngleOffset = v; render(); };
  window.toggle_showLengths = function (on) { state.lengths = on; render(); };
  window.set_activeSet = function (v) { state.active = v; render(); };
  window.trigger_reset = function () {
    O.x = defaults.O.x; O.y = defaults.O.y;
    ['P', 'Q', 'R'].forEach(function (k) {
      trans[k].p.x = defaults.trans[k].p.x;
      trans[k].p.y = defaults.trans[k].p.y;
      trans[k].ang = defaults.trans[k].ang;
    });
    render();
  };

  // ---------- demo steps ----------
  var steps = [
    { title: 'A pencil of four rays', n: 'Four lines radiate from the projection center O. Think of O as a camera pinhole and the rays as sight-lines to four collinear world points.', s: { activeSet: 'all', showLengths: false, rLineAngle: 0 } },
    { title: 'The first cut: P₁…P₄', n: 'A transversal slices the pencil at P₁…P₄. This quadruple is one "image" of the scene; its cross-ratio (P₁P₃·P₂P₄)/(P₂P₃·P₁P₄) appears in the readout above.', s: { activeSet: 'P', showLengths: true, rLineAngle: 0 } },
    { title: 'A second cut, different distances', n: 'The Q transversal cuts the same four rays at very different spacings — every individual length has changed — but the cross-ratio readout is identical.', s: { activeSet: 'Q', showLengths: true, rLineAngle: 0 } },
    { title: 'Drag anything you like', n: 'Drag the crimson transversals or drag O itself. Lengths, angles and ordering on screen all shift, yet the three cross-ratio numbers stay welded together.', s: { activeSet: 'all', showLengths: true, rLineAngle: 0 } },
    { title: 'Sending R₁ to infinity', n: 'The R transversal is parallel to ray 1, so R₁ runs off the page. The cross-ratio does not break — it becomes the plain ratio R₂R₄/R₂R₃. Move the slider away from 0 to bring R₁ back from infinity.', s: { activeSet: 'R', showLengths: true, rLineAngle: 0 } },
    { title: 'One invariant, three views', n: 'All three quadruples — including the degenerate one containing a point at infinity — share a single number. That number is a property of the 3D scene recoverable from one image.', s: { activeSet: 'all', showLengths: false, rLineAngle: 0 } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    document.getElementById('demoNarration').innerHTML = '<b>' + st.title + '</b><br>' + st.n;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    var a = document.getElementById('activeSetInput'); a.value = st.s.activeSet; state.active = st.s.activeSet;
    var c = document.getElementById('showLengthsInput'); c.checked = st.s.showLengths; state.lengths = st.s.showLengths;
    var r = document.getElementById('rLineAngleInput'); r.value = st.s.rLineAngle;
    document.getElementById('rLineAngleVal').value = st.s.rLineAngle;
    rAngleOffset = st.s.rLineAngle;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

